const express = require('express');const http = require('http');
const { Server } = require('socket.io');
const cors = require('cors');


const app = express();
app.use(cors());


const server = http.createServer(app);
const io = new Server(server, {
  cors: {
    origin: "*",
    methods: ["GET", "POST"]
  }
});


// Estado del partido
const players = {};
let ball = {
  x: 0,
  y: 1,
  z: 0,
  vx: 0,
  vy: 0,
  vz: 0
};
let score = { red: 0, blue: 0 };


io.on('connection', (socket) => {
  console.log(`Jugador conectado: ${socket.id}`);


  // Asignar equipo automáticamente (Rojo o Azul)
  const team = Object.keys(players).length % 2 === 0 ? 'red' : 'blue';


  players[socket.id] = {
    id: socket.id,
    team: team,
    x: team === 'red' ? -10 : 10,
    y: 1,
    z: 0,
    ry: 0,
    action: 'idle' // idle, run, shoot, skill
  };


  // Enviar estado inicial al jugador que entra
  socket.emit('init', {
    id: socket.id,
    players,
    ball,
    score
  });


  // Avisar a los demás que entró un jugador
  socket.broadcast.emit('playerJoined', players[socket.id]);


  // Actualizar posición y animación del jugador
  socket.on('move', (data) => {
    if (players[socket.id]) {
      players[socket.id].x = data.x;
      players[socket.id].y = data.y;
      players[socket.id].z = data.z;
      players[socket.id].ry = data.ry;
      players[socket.id].action = data.action || 'run';
      socket.broadcast.emit('playerMoved', players[socket.id]);
    }
  });


  // Patear la pelota (normal o habilidad anime)
  socket.on('kickBall', (data) => {
    ball.vx = data.vx;
    ball.vy = data.vy;
    ball.vz = data.vz;
    io.emit('ballKicked', {
      by: socket.id,
      skill: data.skill || null,
      ball
    });
  });


  // Desconexión
  socket.on('disconnect', () => {
    console.log(`Jugador desconectado: ${socket.id}`);
    delete players[socket.id];
    io.emit('playerLeft', socket.id);
  });
});


// Bucle de física básico de la pelota (30 FPS)
setInterval(() => {
  ball.x += ball.vx * 0.033;
  ball.y += ball.vy * 0.033;
  ball.z += ball.vz * 0.033;


  // Gravedad y rebote en el suelo
  if (ball.y > 1) {
    ball.vy -= 9.8 * 0.033;
  } else {
    ball.y = 1;
    ball.vy = Math.abs(ball.vy) > 0.5 ? -ball.vy * 0.6 : 0;
  }


  // Fricción del césped
  ball.vx *= 0.96;
  ball.vz *= 0.96;


  // Detección simple de gol (cancha de -50 a 50 en X)
  if (ball.x > 50) {
    score.red++;
    resetBall();
    io.emit('goal', { team: 'red', score });
  } else if (ball.x < -50) {
    score.blue++;
    resetBall();
    io.emit('goal', { team: 'blue', score });
  }


  io.emit('ballUpdate', ball);
}, 33);


function resetBall() {
  ball = { x: 0, y: 2, z: 0, vx: 0, vy: 0, vz: 0 };
}


const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Servidor corriendo en el puerto ${PORT}`);
});

